import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CsGzzEsd.js";const m=JSON.parse('{"title":"CFA Level II Plan","description":"","frontmatter":{"title":"CFA Level II Plan"},"headers":[],"relativePath":"blogs/CFA/plan.md","filePath":"blogs/CFA/plan.md"}'),n={name:"blogs/CFA/plan.md"};function s(r,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="cfa-level-ii-learning-plan" tabindex="-1">CFA Level II Learning Plan <a class="header-anchor" href="#cfa-level-ii-learning-plan" aria-label="Permalink to &quot;CFA Level II Learning Plan&quot;">​</a></h1><blockquote><p><strong>Working assumption:</strong> a 24-week runway and about <strong>12 hours per week</strong>. If the exam is closer, keep the sequence but compress the first two phases; do not cut the final review and mock phase.</p></blockquote><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><ul><li>Complete every curriculum reading and its end-of-reading questions.</li><li>Build one compact formula-and-errors notebook, not a second textbook.</li><li>Reach <strong>70%+ across three timed mocks</strong>, with no topic repeatedly below 60%.</li><li>Explain each major valuation method, assumption, and common trap without notes.</li></ul><h2 id="weekly-rhythm" tabindex="-1">Weekly rhythm <a class="header-anchor" href="#weekly-rhythm" aria-label="Permalink to &quot;Weekly rhythm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Session</th><th style="text-align:right;">Time</th><th>Work</th></tr></thead><tbody><tr><td>3 weekday sessions</td><td style="text-align:right;">90 min each</td><td>Learn one concept block, then do 15–25 questions closed-book.</td></tr><tr><td>1 short weekday session</td><td style="text-align:right;">45 min</td><td>Formula recall and error-log review.</td></tr><tr><td>Weekend deep work</td><td style="text-align:right;">5–6 hr</td><td>Finish the topic set, mixed practice, and one item-set review.</td></tr></tbody></table><p>Use a <strong>40/60 split</strong>: no more than 40% reading or watching; at least 60% retrieval, calculation, and item-set practice.</p><h2 id="_24-week-roadmap" tabindex="-1">24-week roadmap <a class="header-anchor" href="#_24-week-roadmap" aria-label="Permalink to &quot;24-week roadmap&quot;">​</a></h2><h3 id="phase-1-—-map-and-diagnose-weeks-1–2" tabindex="-1">Phase 1 — Map and diagnose (Weeks 1–2) <a class="header-anchor" href="#phase-1-—-map-and-diagnose-weeks-1–2" aria-label="Permalink to &quot;Phase 1 — Map and diagnose (Weeks 1–2)&quot;">​</a></h3><ul><li>Confirm the exam date and current curriculum version in the CFA candidate resources.</li><li>Take a 60–90 question diagnostic without preparation.</li><li>Tag every miss: <code>knowledge</code>, <code>formula</code>, <code>interpretation</code>, <code>calculator</code>, or <code>time</code>.</li><li>Set up one error log: question source, why the wrong answer felt right, correct rule, revisit date.</li></ul><h3 id="phase-2-—-first-pass-weeks-3–14" tabindex="-1">Phase 2 — First pass (Weeks 3–14) <a class="header-anchor" href="#phase-2-—-first-pass-weeks-3–14" aria-label="Permalink to &quot;Phase 2 — First pass (Weeks 3–14)&quot;">​</a></h3><p>Study in an order that compounds understanding:</p><ol><li>Quantitative Methods and Economics</li><li>Financial Statement Analysis</li><li>Corporate Issuers</li><li>Equity Valuation</li><li>Fixed Income</li><li>Derivatives</li><li>Alternative Investments</li><li>Portfolio Management</li></ol><p>Keep Ethics active with one short set every week. At the end of each topic, complete a timed mixed set and write a one-page synthesis: key decisions, formulas, and failure modes.</p><h3 id="phase-3-—-integration-weeks-15–19" tabindex="-1">Phase 3 — Integration (Weeks 15–19) <a class="header-anchor" href="#phase-3-—-integration-weeks-15–19" aria-label="Permalink to &quot;Phase 3 — Integration (Weeks 15–19)&quot;">​</a></h3><ul><li>Replace chapter-by-chapter work with mixed item sets.</li><li>Run two 45–60 minute timed blocks each week.</li><li>Rework every logged error after 2 days, 1 week, and 3 weeks.</li><li>Pair related areas: FSA ↔ equity, economics ↔ portfolio management, fixed income ↔ derivatives.</li><li>Finish each week with a scorecard by topic and error type.</li></ul><h3 id="phase-4-—-exam-mode-weeks-20–23" tabindex="-1">Phase 4 — Exam mode (Weeks 20–23) <a class="header-anchor" href="#phase-4-—-exam-mode-weeks-20–23" aria-label="Permalink to &quot;Phase 4 — Exam mode (Weeks 20–23)&quot;">​</a></h3><ul><li>Complete one full timed mock each weekend under exam conditions.</li><li>Spend at least as long reviewing a mock as taking it.</li><li>On weekdays, repair the two weakest topics only; avoid random rereading.</li><li>Recreate the core formula sheet from memory once per week.</li></ul><h3 id="phase-5-—-taper-week-24" tabindex="-1">Phase 5 — Taper (Week 24) <a class="header-anchor" href="#phase-5-—-taper-week-24" aria-label="Permalink to &quot;Phase 5 — Taper (Week 24)&quot;">​</a></h3><ul><li>Do short, high-quality mixed sets; stop full mocks several days before the exam.</li><li>Review Ethics, formulas, recurring errors, calculator steps, and exam logistics.</li><li>Protect sleep and preserve confidence; add no new resources.</li></ul><h2 id="weekly-review-template" tabindex="-1">Weekly review template <a class="header-anchor" href="#weekly-review-template" aria-label="Permalink to &quot;Weekly review template&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>Hours planned / completed:</span></span>
<span class="line"><span>Questions attempted / accuracy:</span></span>
<span class="line"><span>Weakest topic and error pattern:</span></span>
<span class="line"><span>One concept I can now teach:</span></span>
<span class="line"><span>One change for next week:</span></span></code></pre></div><h2 id="first-seven-days" tabindex="-1">First seven days <a class="header-anchor" href="#first-seven-days" aria-label="Permalink to &quot;First seven days&quot;">​</a></h2><ul><li>[ ] Record the exam date, remaining weeks, and weekly time budget.</li><li>[ ] Take and score the diagnostic.</li><li>[ ] Create the error log and formula deck.</li><li>[ ] Choose the first two topic blocks.</li><li>[ ] Put all sessions on the calendar before the week begins.</li></ul>`,24)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
